css.banco-detras.html:
/* Página: cabecera + barra fija de filtros + rejilla de fichas (pantalla 9:16 que se mueve, voto debajo) */
:root{--bg:#f3f1ee;--panel:#fff;--ink:#17171c;--mute:#6c6a73;--line:#e1ddd8;--accent:#E98A55;--accent-ink:#fff;--yes:#16a34a;--yes-bg:#dcf5e5;--no:#d62f4b;--no-bg:#fde3e8}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#121216;--panel:#1c1c22;--ink:#f2f0ed;--mute:#9b98a3;--line:#2e2e36;--accent:#F4A57A;--accent-ink:#1d0f06;--yes:#4ade80;--yes-bg:#12301e;--no:#ff6b84;--no-bg:#3a141d;color-scheme:dark}}
:root[data-theme="dark"]{--bg:#121216;--panel:#1c1c22;--ink:#f2f0ed;--mute:#9b98a3;--line:#2e2e36;--accent:#F4A57A;--accent-ink:#1d0f06;--yes:#4ade80;--yes-bg:#12301e;--no:#ff6b84;--no-bg:#3a141d;color-scheme:dark}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font:400 14px/1.45 Inter,system-ui,sans-serif;padding:28px 16px 40px}
.wrap{max-width:1180px;margin:0 auto}
h1{font:800 30px/1.1 Archivo,Inter,sans-serif;margin:0 0 8px;letter-spacing:-.02em;text-wrap:balance}
.lead{max-width:66ch;color:var(--mute);margin:0 0 20px}
.bar{position:sticky;top:0;z-index:20;background:var(--bg);padding:10px 0;border-bottom:1px solid var(--line);display:flex;flex-wrap:wrap;gap:10px 16px;align-items:center;margin-bottom:22px}
.chips{display:flex;flex-wrap:wrap;gap:6px}
.chip{border:1px solid var(--line);background:var(--panel);color:var(--ink);border-radius:999px;padding:6px 12px;font:600 12px Inter,sans-serif;cursor:pointer}
.chip[aria-pressed="true"]{background:var(--ink);color:var(--bg);border-color:var(--ink)}
.chip:focus-visible,.vb:focus-visible,.copy:focus-visible,.stage:focus-visible,textarea:focus-visible,input:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.count{margin-left:auto;font-size:12px;color:var(--mute);font-variant-numeric:tabular-nums}
.copy{background:var(--accent);color:var(--accent-ink);border:0;border-radius:10px;padding:9px 16px;font:800 13px Inter,sans-serif;cursor:pointer}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(248px,1fr));gap:18px}
.card{background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:14px;display:flex;flex-direction:column;gap:10px;min-width:0}
.card[data-v="1"]{border-color:var(--yes);box-shadow:0 0 0 2px var(--yes-bg)}
.card[data-v="-1"]{opacity:.62}
.card[data-v="-1"] .stage{filter:grayscale(.6)}
.meta{display:flex;flex-direction:column;gap:3px}
.nm{font:800 15px/1.2 Archivo,Inter,sans-serif}
.fr{font:600 10px Inter,sans-serif;letter-spacing:.06em;text-transform:uppercase;color:var(--mute)}
.ds{font-size:12.5px;color:var(--mute)}
.votes{display:flex;gap:8px}
.vb{flex:1;border:1px solid var(--line);background:var(--bg);color:var(--ink);border-radius:10px;padding:9px 6px;font:700 13px Inter,sans-serif;cursor:pointer}
.vb.y[aria-pressed="true"]{background:var(--yes);border-color:var(--yes);color:#fff}
.vb.n[aria-pressed="true"]{background:var(--no);border-color:var(--no);color:#fff}
.note{width:100%;border:1px solid var(--line);background:var(--bg);color:var(--ink);border-radius:8px;padding:7px 9px;font:400 12px Inter,sans-serif}
.out{margin-top:30px;background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:16px}
.out h2{margin:0 0 6px;font:800 18px Archivo,Inter,sans-serif}
.out p{margin:0 0 10px;color:var(--mute);font-size:13px}
textarea{width:100%;min-height:200px;border:1px solid var(--line);border-radius:10px;background:var(--bg);color:var(--ink);padding:10px;font:12px/1.5 ui-monospace,Menlo,monospace}
.empty{padding:40px 0;color:var(--mute);text-align:center}

/* ===== piezas (sobre su propio fondo; no cambian con el tema) =====
   Capas: .fondo (el salón = su vídeo) → los elementos → .persona (ella recortada, SIEMPRE delante). */
.stage{position:relative;width:216px;height:384px;border-radius:22px;overflow:hidden;margin:0 auto;box-shadow:0 6px 18px rgba(0,0,0,.18);cursor:pointer;max-width:100%;isolation:isolate;color:#17171c;font-family:Inter,sans-serif}
.fondo{position:absolute;inset:0;background:linear-gradient(180deg,#f1e8de 0,#e9dccd 58%,#cdb59c 100%)}
.fondo::before{content:"";position:absolute;left:14px;top:46px;width:54px;height:150px;border-radius:6px;background:linear-gradient(180deg,#dfe3e2,#c9cfcd);box-shadow:150px 0 0 #d9dedd}
.fondo::after{content:"";position:absolute;left:-10px;right:-10px;top:250px;height:40px;background:radial-gradient(60% 100% at 50% 0,rgba(255,170,110,.35),transparent 70%)}
.persona{position:absolute;inset:0;z-index:10;pointer-events:none}
.persona .pl{position:absolute;left:74px;top:100px;width:68px;height:104px;border-radius:34px 34px 20px 20px;background:linear-gradient(180deg,#c4602f,#9c4220)}
.persona .pb{position:absolute;left:36px;right:36px;top:176px;bottom:-30px;border-radius:64px 64px 0 0;background:linear-gradient(180deg,#26232a,#151417);box-shadow:0 -2px 14px rgba(0,0,0,.25)}
.persona .pn{position:absolute;left:98px;top:156px;width:20px;height:30px;background:#e2ad8b;border-radius:0 0 8px 8px}
.persona .ph{position:absolute;left:84px;top:110px;width:48px;height:58px;border-radius:46% 46% 48% 48%;background:#ebbb99}
.persona .ph::before{content:"";position:absolute;left:-4px;right:-4px;top:-6px;height:24px;border-radius:50% 50% 30% 30%;background:#bd5a2a}
.persona .ph::after{content:"";position:absolute;left:14px;top:30px;width:4px;height:4px;border-radius:50%;background:#3a2418;box-shadow:16px 0 0 #3a2418}
.abs{position:absolute}
.cd{position:absolute;background:#fff;border-radius:12px;box-shadow:0 10px 22px rgba(0,0,0,.16),0 1px 3px rgba(0,0,0,.08);padding:8px 9px}
.cdk{position:absolute;background:#242424;color:#fff;border-radius:12px;box-shadow:0 12px 24px rgba(0,0,0,.3);padding:8px 9px}
.t{font:800 11px/1.15 Inter,sans-serif;color:#17171c;white-space:nowrap}
.t2{font:600 8px/1.2 Inter,sans-serif;color:#777}
.ln{display:block;height:5px;border-radius:3px;background:#e7e2dc;margin-top:6px}
.pill{position:absolute;display:inline-block;background:#E98A55;color:#fff;font:800 10px/1 Inter,sans-serif;border-radius:99px;padding:6px 10px;white-space:nowrap;box-shadow:0 6px 14px rgba(233,138,85,.35)}
.pillw{position:absolute;display:inline-block;background:#fff;color:#17171c;font:800 10px/1 Inter,sans-serif;border-radius:99px;padding:6px 10px;white-space:nowrap;box-shadow:0 6px 14px rgba(0,0,0,.15)}
.big{font-family:'Archivo Black',Archivo,sans-serif;letter-spacing:-.02em;line-height:.9;color:#17171c}
.vd{position:absolute;border-radius:12px;overflow:hidden;background:linear-gradient(160deg,var(--v1,#e7c7a6),var(--v2,#8a5233));box-shadow:0 12px 24px rgba(0,0,0,.22)}
.vd::before{content:"";position:absolute;left:50%;bottom:-6%;width:56%;height:62%;transform:translateX(-50%);border-radius:50% 50% 0 0/40% 40% 0 0;background:radial-gradient(circle at 50% 22%,var(--v3,#f0c7a4) 0 18%,transparent 19%),linear-gradient(180deg,transparent 30%,rgba(40,25,18,.55) 31%)}
.vd::after{content:"";position:absolute;inset:0;background:linear-gradient(110deg,transparent 30%,rgba(255,255,255,.32) 50%,transparent 70%);background-size:220% 100%;animation:kFoot 2.4s linear infinite}
.vd .vb2{position:absolute;left:8px;right:8px;bottom:7px;height:3px;border-radius:2px;background:rgba(255,255,255,.35)}
.vd .vb2::after{content:"";position:absolute;left:0;top:0;bottom:0;width:100%;border-radius:2px;background:#fff;transform-origin:left;animation:kGrowX 4.2s linear both}
.ck{display:inline-grid;place-items:center;width:13px;height:13px;border-radius:50%;background:#18a957;color:#fff;font:900 8px/1 Inter,sans-serif;flex:none}
.row{display:flex;align-items:center;gap:6px;margin-top:6px}
.bot{position:absolute;bottom:0;border-radius:7px 7px 4px 4px;background:linear-gradient(90deg,#fff,#efe9e3);box-shadow:0 8px 16px rgba(0,0,0,.18)}
.bot::before{content:"";position:absolute;left:28%;right:28%;top:-9px;height:10px;border-radius:3px 3px 0 0;background:#242424}
.bot::after{content:"";position:absolute;left:12%;right:12%;top:38%;height:22%;border-radius:3px;background:#E98A55;opacity:.85}

@keyframes kFoot{from{background-position:120% 0}to{background-position:-120% 0}}
@keyframes kGrowX{from{transform:scaleX(0)}to{transform:scaleX(1)}}
@keyframes kGrowY{from{transform:scaleY(0)}to{transform:scaleY(1)}}
@keyframes kFd{from{opacity:0}to{opacity:1}}
@keyframes kUp{from{opacity:0;transform:translateY(24px)}to{opacity:1;transform:none}}
@keyframes kRise{from{transform:translateY(150px)}to{transform:none}}
@keyframes kOutR{from{transform:translateX(-80px)}to{transform:none}}
@keyframes kOutL{from{transform:translateX(80px)}to{transform:none}}
@keyframes kScale{from{transform:scale(0)}to{transform:scale(1)}}
@keyframes kPop{from{opacity:0;transform:scale(.7)}to{opacity:1;transform:scale(1)}}
@keyframes kDrop{from{transform:translateY(-190px)}to{transform:none}}
@keyframes kGlide{from{transform:translateX(-200px)}to{transform:translateX(260px)}}
@keyframes kClipC{from{clip-path:inset(50% 50% 50% 50% round 12px)}to{clip-path:inset(0 0 0 0 round 12px)}}
@keyframes kClipUp{from{clip-path:inset(100% 0 0 0)}to{clip-path:inset(0 0 0 0)}}
@keyframes kClipR{from{clip-path:inset(0 100% 0 0)}to{clip-path:inset(0 0 0 0)}}
@keyframes kBlurIn{from{filter:blur(8px);transform:scale(1.12);opacity:.4}to{filter:blur(0);transform:none;opacity:1}}
@keyframes kFar{from{transform:scale(.45);opacity:0;filter:blur(3px)}to{transform:none;opacity:1;filter:blur(0)}}
@keyframes kSweep{from{transform:translateX(-140px) skewX(-18deg)}to{transform:translateX(260px) skewX(-18deg)}}
@keyframes kFull{from{clip-path:inset(26% 32% 44% 32% round 14px)}to{clip-path:inset(0 0 0 0 round 0)}}
@keyframes kStrip{from{transform:translateX(0)}to{transform:translateX(-156px)}}
@keyframes kSwap1{0%,32%{opacity:1}36%,100%{opacity:0}}
@keyframes kSwap2{0%,32%{opacity:0}36%,66%{opacity:1}70%,100%{opacity:0}}
@keyframes kSwap3{0%,66%{opacity:0}70%,100%{opacity:1}}
@keyframes kDraw{from{stroke-dashoffset:1}to{stroke-dashoffset:0}}
@keyframes kType{from{width:0}to{width:var(--w,120px)}}
@keyframes kFan1{from{transform:none}to{transform:translate(-62px,8px)}}
@keyframes kFan3{from{transform:none}to{transform:translate(62px,8px)}}
@keyframes kCar{from{transform:translateX(0)}to{transform:translateX(-210px)}}
@keyframes kPx1{from{transform:translateX(-6px)}to{transform:translateX(6px)}}
@keyframes kPx2{from{transform:translateX(-14px)}to{transform:translateX(14px)}}
@keyframes kPx3{from{transform:translateX(-26px)}to{transform:translateX(26px)}}
@keyframes kWipe{from{clip-path:inset(0 100% 0 0)}to{clip-path:inset(0 0 0 0)}}
@keyframes kGlow{from{transform:scale(.3);opacity:0}to{transform:scale(1);opacity:1}}
@keyframes kPush{from{transform:scale(1)}to{transform:scale(1.12)}}
@keyframes kPushBack{from{transform:scale(1)}to{transform:scale(1.32)}}
@keyframes kGray{from{filter:none}to{filter:grayscale(1) brightness(.95)}}
@keyframes kDim{to{opacity:.35}}
@keyframes kBg{from{opacity:0}to{opacity:1}}
@keyframes kStack{from{opacity:0;transform:translateY(90px)}to{opacity:1;transform:none}}
@keyframes kRank{from{opacity:0;transform:translateX(-30px)}to{opacity:1;transform:none}}
@keyframes kSwing{from{transform:translateX(-90px)}to{transform:none}}
@keyframes kPrint{from{clip-path:inset(100% 0 0 0)}to{clip-path:inset(0 0 0 0)}}
@keyframes kBlink{0%,49%{opacity:1}50%,100%{opacity:0}}
